  it.each<[string, (i: Mut) => void, string]>([
    [
      'no mint transaction',
      (i) => {
        delete i.ledger.mintTx;
      },
      'MINT_NOT_VALIDATED',
    ],
    [
      'a failed mint',
      (i) => {
        i.ledger.mintTx.meta.TransactionResult = 'tecNO_PERMISSION';
      },
      'MINT_NOT_APPLIED',
    ],
    [
