      (i) => {
        i.ledger.mintTx.ledger_index = LEDGER.index + 1;
      },
      'MINT_NOT_APPLIED',
    ],
    [
      'meta names another NFT',
      (i) => {
        i.ledger.mintTx.meta.nftoken_id = nftokenId(OPS.LA.address, 9);
      },
      'NFT_ID_MISMATCH',
    ],
    [
      'an NFTokenID whose flags differ from the mint',
