        i.deal.nftokenId = nftokenId(OPS.LA.address, 9);
        i.ledger.mintTx.meta.nftoken_id = i.deal.nftokenId;
      },
      'NFT_ID_MISMATCH',
    ],
  ])('%s', (_what, change, code) => {
